// Regenerates content/index.ts so it imports every file in content/{pages,case-studies,blog,articles}.
// Run after adding or removing a content file:  npm run content:index
import fs from "node:fs";

const groups = { pages: "Page", "case-studies": "CaseStudy", blog: "Post", articles: "Post" };
const ident = (dir, file) => `${dir}_${file}`.replace(/[^A-Za-z0-9]/g, "_");

const out = [
  "// Auto-generated by scripts/gen-index.mjs — lists every content file.",
  'import type { Page, CaseStudy, Post } from "./types";',
];
const names = {};
for (const dir of Object.keys(groups)) {
  names[dir] = fs.readdirSync(`content/${dir}`).filter((f) => f.endsWith(".ts")).map((f) => f.slice(0, -3)).sort();
  for (const f of names[dir]) out.push(`import ${ident(dir, f)} from "./${dir}/${f}";`);
}
const list = (dir) => names[dir].map((f) => ident(dir, f)).join(", ");
out.push(
  "",
  `export const pages: Page[] = [${list("pages")}];`,
  `export const caseStudies: CaseStudy[] = [${list("case-studies")}];`,
  `export const blogPosts: Post[] = [${list("blog")}];`,
  `export const articles: Post[] = [${list("articles")}];`,
);
fs.writeFileSync("content/index.ts", out.join("\n") + "\n");
console.log("content/index.ts updated");
